{"command":"set -e
q() {
  local name="$1" ver="$2"
  echo "=== $name @ $ver ==="
  curl -sS -m 15 -X POST https://api.osv.dev/v1/query \
    -H "Content-Type: application/json" \
    -d "{\"package\": {\"name\": \"$name\", \"ecosystem\": \"Maven\"}, \"version\": \"$ver\"}" \
    | node -e '
      let d="";process.stdin.on("data",c=>d+=c);process.stdin.on("end",()=>{
        try{const j=JSON.parse(d);
        if(!j.vulns){console.log("(no vulns field / empty)");console.log(d.slice(0,300));return;}
        for(const v of j.vulns){
          console.log(v.id, "|", (v.summary||"").slice(0,140));
          if(v.aliases) console.log("  aliases:", v.aliases.join(", "));
          if(v.affected){
            for(const a of v.affected){
              if(a.ranges) for(const r of a.ranges){ console.log("  range:", JSON.stringify(r.events)); }
            }
          }
        }
        }catch(e){console.log("parse error", e.message, d.slice(0,300));}
      });'
  echo
}
